  "lead_interested/rj_ai/v1": "import type { ScriptContext, ScriptResult } from \"@gtm-factory/core\";\n\n/** Reads the reply and our message; answers interested or not. */\nexport default function run(ctx: ScriptContext): ScriptResult {\n  const reply = ctx.get(\"reply_received\");\n  const llm = ctx.get(\"llm_completion\");\n  ctx.get(\"rating\");\n  const r = ctx.vendor.call(\"llm.judge\", { reply: reply.id, model: llm.content.model, question: \"Is this person interested?\" });\n  return r.ok ? { content: { verdict: \"interested\" } } : null;\n}\n",
  "lead_interested/web_signup/v1": "import type { ScriptContext, ScriptResult } from \"@gtm-factory/core\";\n\n/** The client's website: a visitor signs up or books a demo. */\nexport default function run(ctx: ScriptContext): ScriptResult {\n  ctx.get(\"lead_visited\");\n  ctx.get(\"rating\");\n  const r = ctx.vendor.call(\"website.form\");\n  return r.ok ? { content: { form: \"signup\" } } : null;\n}\n",
  "lead_visited/ad_search/v1": "import type { ScriptContext, ScriptResult } from \"@gtm-factory/core\";\n\n/** A search ad shown to people who fit the ICP; a click is a visit. */\nexport default function run(ctx: ScriptContext): ScriptResult {\n  const icp = ctx.get(\"audience_built\");\n  ctx.get(\"rating\");\n  for (let k = 0; k < 60; k++) {\n    const drawn = ctx.vendor.call(\"market.draw\", { source: \"Google search\", icp: icp.id });\n    if (!drawn.ok) return null;\n    const key = String(drawn.data.key);\n    if (ctx.storage.get(\"shown\", key) !== undefined) continue;\n    if (!ctx.vendor.call(\"market.fits\", { key, icp: icp.id }).ok) continue;\n    ctx.storage.set(\"shown\", key, ctx.day);\n    return { found: key };\n  }\n  return null;\n}\n",
  "lead_visited/ad_social/v1": "import type { ScriptContext, ScriptResult } from \"@gtm-factory/core\";\n\n/** A Meta ad shown to people who fit the ICP; a click is a visit. */\nexport default function run(ctx: ScriptContext): ScriptResult {\n  const icp = ctx.get(\"audience_built\");\n  ctx.get(\"rating\");\n  for (let k = 0; k < 60; k++) {\n    const drawn = ctx.vendor.call(\"market.draw\", { source: \"Meta\", icp: icp.id });\n    if (!drawn.ok) return null;\n    const key = String(drawn.data.key);\n    if (ctx.storage.get(\"shown\", key) !== undefined) continue;\n    if (!ctx.vendor.call(\"market.fits\", { key, icp: icp.id }).ok) continue;\n    ctx.storage.set(\"shown\", key, ctx.day);\n    return { found: key };\n  }\n  return null;\n}\n",
  "llm_completion/gemini_flash/v1": "import type { ScriptContext, ScriptResult } from \"@gtm-factory/core\";\n\n/** One answer of gemini-3.7-flash to the run that ordered it. */\nexport default function run(ctx: ScriptContext): ScriptResult {\n  const r = ctx.vendor.call(\"llm.complete\", { model: \"gemini-3.7-flash\" });\n  return r.ok ? { content: { model: \"gemini-3.7-flash\", text: String(r.data.text ?? \"\") } } : null;\n}\n",
