  "message_sent/mb_send/v1": "import type { ScriptContext, ScriptResult } from \"@gtm-factory/core\";\n\n/** The mailbox reports each message it sent (SMTP acceptance). Called by another party: it reports, it is never ordered. */\nexport default function run(ctx: ScriptContext): ScriptResult {\n  const r = ctx.vendor.call(\"webhook.report\");\n  return r.ok ? { content: {} } : null;\n}\n",
  "message_written/wr_research/v1": "import type { ScriptContext, ScriptResult } from \"@gtm-factory/core\";\n\n/** Researches the company first, then writes from the template and the brand context. */\nexport default function run(ctx: ScriptContext): ScriptResult {\n  const email = ctx.get(\"email_found\");\n  const company = ctx.get(\"company_researched\");\n  const template = ctx.get(\"template_written\");\n  let context = ctx.get(\"brand_context\");\n  if (context.ageDays > 90) context = ctx.get(\"brand_context\");\n  const llm = ctx.get(\"llm_completion\");\n  ctx.get(\"rating\");\n  const r = ctx.vendor.call(\"llm.complete\", { template: template.content.text, context: context.content.summary, company: company.content, model: llm.content.model, to: email.subject });\n  return r.ok ? { content: { body: String(r.data.text ?? \"\"), template: template.id } } : null;\n}\n",
  "message_written/wr_short/v1": "import type { ScriptContext, ScriptResult } from \"@gtm-factory/core\";\n\n/** Writes a short email from the template and the brand context, without a company research. */\nexport default function run(ctx: ScriptContext): ScriptResult {\n  const email = ctx.get(\"email_found\");\n  const template = ctx.get(\"template_written\");\n  let context = ctx.get(\"brand_context\");\n  if (context.ageDays > 90) context = ctx.get(\"brand_context\");\n  const llm = ctx.get(\"llm_completion\");\n  ctx.get(\"rating\");\n  const r = ctx.vendor.call(\"llm.complete\", { template: template.content.text, context: context.content.summary, model: llm.content.model, to: email.subject });\n  return r.ok ? { content: { body: String(r.data.text ?? \"\"), template: template.id } } : null;\n}\n",
  "offer_described/offer_client/v1": "import type { ScriptContext, ScriptResult } from \"@gtm-factory/core\";\n\n/** The client types its offer when the brand is added: nothing to call. */\nexport default function run(ctx: ScriptContext): ScriptResult {\n  const r = ctx.vendor.call(\"client.form\", { field: \"offer\" });\n  return r.ok ? { content: { text: String(r.data.text ?? \"\") } } : null;\n}\n",
  "paid_client/cl_call/v1": "import type { ScriptContext, ScriptResult } from \"@gtm-factory/core\";\n\n/** The client's team runs the closing call. */\nexport default function run(ctx: ScriptContext): ScriptResult {\n  ctx.get(\"meeting_attended\");\n  const r = ctx.vendor.call(\"team.close\");\n  return r.ok ? { content: { closed: true } } : null;\n}\n",
  "rating/rating_pooled/v1": "import type { ScriptContext, ScriptResult } from \"@gtm-factory/core\";\n\n/** Reads the ledger and the traceability; GTM Factory turns it into today's beliefs about value per dollar. */\nexport default function run(ctx: ScriptContext): ScriptResult {\n  const r = ctx.vendor.call(\"ledger.read\");\n  return r.ok ? { content: {} } : null;\n}\n",
  "reply_received/li_connect/v1": "import type { ScriptContext, ScriptResult } from \"@gtm-factory/core\";\n\n/** Sends a LinkedIn connection with a note written from the template; an answer is a reply. */\nexport default function run(ctx: ScriptContext): ScriptResult {\n  const lead = ctx.get(\"lead_identified\");\n  const template = ctx.get(\"template_written\");\n  const llm = ctx.get(\"llm_completion\");\n  ctx.get(\"rating\");\n  const r = ctx.vendor.call(\"linkedin.connect\", { lead: lead.subject, template: template.content.text, model: llm.content.model });\n  return r.ok ? { content: { channel: \"LinkedIn\", text: String(r.data.text ?? \"\") } } : null;\n}\n",
  "reply_received/mb_fu_replies/v1": "import type { ScriptContext, ScriptResult } from \"@gtm-factory/core\";\n\n/** Reads our mailboxes and matches each answer to the follow-up it answers. */\nexport default function run(ctx: ScriptContext): ScriptResult {\n  ctx.get(\"follow_up_queued\");\n  const r = ctx.vendor.call(\"imap.read\");\n  return r.ok ? { content: { thread: true } } : null;\n}\n",
